const trigger = $('Profile Info from front (CV pdf, City, Position)').first().json;
const body = trigger.body || {};
const cvText = $('Extract CV text').first().json.text || '';
const raw = $input.first().json;
const d = raw.output ?? raw;

// Try to decode first/last name + email from the Supabase JWT in the Authorization header
function decodeJwt(headers) {
  try {
    const auth = (headers && (headers.authorization || headers.Authorization)) || '';
    const token = auth.replace(/^Bearer\s+/i, '');
    const parts = token.split('.');
    if (parts.length < 2) return {};
    let b64 = parts[1].replace(/-/g, '+').replace(/_/g, '/');
    while (b64.length % 4) b64 += '=';
    return JSON.parse(Buffer.from(b64, 'base64').toString('utf8')) || {};
  } catch (e) {
    return {};
  }
}
const jwt = decodeJwt(trigger.headers);
const meta = jwt.user_metadata || {};

function toArray(value) {
  if (Array.isArray(value)) return value;
  if (value === null || value === undefined || value === '') return [];
  return String(value).split(/[\n,;]+/).map(x => x.trim()).filter(Boolean);
}
function toNum(value) {
  if (value === null || value === undefined || value === '') return null;
  const n = Number(String(value).replace(/[^0-9.]/g, ''));
  return Number.isFinite(n) ? n : null;
}
function clean(value) {
  return value === null || value === undefined ? '' : String(value).trim();
}
// Accepts "linkedin.com/in/x", "www.linkedin.com/in/x/", "https://nl.linkedin.com/in/x?utm=..." -> "https://www.linkedin.com/in/x".
// Returns '' for anything that is not a LinkedIn profile URL.
function normalizeLinkedin(value) {
  const v = clean(value);
  if (!v) return '';
  const m = v.match(/linkedin\.com\/(in|pub)\/([^/?#\s]+)/i);
  return m ? 'https://www.linkedin.com/' + m[1].toLowerCase() + '/' + m[2] : '';
}

const targetRoles = [];
if (clean(body.position)) targetRoles.push(clean(body.position));

const targetLocations = [];
if (clean(body.city)) targetLocations.push(clean(body.city));

// The URL typed in the frontend wins over the one found in the CV.
const linkedinUrl = normalizeLinkedin(body.linkedin_url ?? body.linkedinUrl) || normalizeLinkedin(d.linkedin_url);

const nowIso = new Date().toISOString();

const row = {
  auth_user_id: clean(body.auth_user_id) || clean(jwt.sub),
  email: clean(body.email) || clean(jwt.email),
  first_name: clean(meta.first_name) || clean(d.first_name),
  last_name: clean(meta.last_name) || clean(d.last_name),
  location: clean(body.city),
  profile_summary: clean(d.profile_summary),
  cv_text: cvText,
  skills_json: JSON.stringify(toArray(d.skills)),
  education_json: JSON.stringify(toArray(d.education)),
  experience_json: JSON.stringify(toArray(d.experience)),
  previous_companies_json: JSON.stringify(toArray(d.previous_companies)),
  preferred_industries_json: JSON.stringify(toArray(d.preferred_industries)),
  target_roles_json: JSON.stringify(targetRoles),
  target_locations_json: JSON.stringify(targetLocations),
  employment_type: clean(d.employment_type),
  remote_preference: clean(d.remote_preference),
  salary_min: toNum(d.salary_min),
  job_search_active: true,
  updated_at: nowIso,
};
// Only write linkedin_url when we have one, so an update without it keeps the stored URL.
if (linkedinUrl) row.linkedin_url = linkedinUrl;

return [{ json: row }];
